// Sounds for the board page, generated by code with the Web Audio API (no audio files).
//
// game.js announces what happens through its cue hook ("active", "slide", "correct",
// "incorrect", "invalid", "win", "lose"). This module turns each cue into oscillator
// tones and owns the looping background music and the mute preference.
//
// Nothing is created before the first user gesture (browsers refuse to play before one),
// and every Web Audio call is guarded: a missing or failing API means silence, never an
// error. Everything above the "Page wiring" section receives its environment as
// arguments, so it can be driven with a fake AudioContext.

import { onCue } from "./game.js";

export const STORAGE_KEY = "juego.sound.muted";

const START_DELAY_S = 0.02; // lead time so a tone never starts in the past
const ATTACK_S = 0.01; // fade-in that avoids a click at the start of a tone
const SILENCE = 0.0001; // exponential ramps cannot reach 0
const LOOKAHEAD_S = 6; // how far ahead the music is scheduled
const CHECK_MS = 1000; // how often the music scheduler tops itself up
const GESTURES = ["pointerdown", "pointerup", "keydown", "click"];

/**
 * One tone: `at` seconds after the cue starts, `freq` Hz gliding to `to`, `dur` seconds
 * long, with a waveform and a peak volume (0 to 1).
 */
function tone(at, freq, dur, type, gain, to = freq) {
  return { at, freq, to, dur, type, gain };
}

// The six one-shot cues. Each differs from the others in register, waveform or contour:
// slide is a short upward swoosh, invalid a low buzz, correct two bright rising dings,
// incorrect one dull falling thud, win a rising fanfare and lose a slow sawtooth fall.
export const CUES = {
  slide: [tone(0, 300, 0.1, "triangle", 0.22, 500)],
  invalid: [tone(0, 180, 0.12, "square", 0.16, 150), tone(0.13, 150, 0.16, "square", 0.16, 110)],
  correct: [tone(0.06, 880, 0.09, "sine", 0.22), tone(0.15, 1320, 0.16, "sine", 0.22)],
  incorrect: [tone(0.06, 240, 0.2, "triangle", 0.26, 170)],
  // Starts a little late so it does not trample the slide and correct cues of the winning move.
  win: [
    tone(0.3, 523.25, 0.18, "square", 0.16),
    tone(0.5, 659.25, 0.18, "square", 0.16),
    tone(0.7, 783.99, 0.18, "square", 0.16),
    tone(0.9, 1046.5, 0.7, "square", 0.16),
    tone(0.9, 783.99, 0.7, "triangle", 0.2),
  ],
  lose: [
    tone(0, 392, 0.35, "sawtooth", 0.16),
    tone(0.4, 311.13, 0.35, "sawtooth", 0.16),
    tone(0.8, 261.63, 0.35, "sawtooth", 0.16),
    tone(1.2, 196, 0.9, "sawtooth", 0.18, 70),
    tone(1.2, 98, 0.9, "sine", 0.3, 49),
  ],
};

// The background music: a quiet A-minor arpeggio over a slow bass, one pass every 4.8 s.
const STEP_S = 0.3;
const MELODY = [220, 329.63, 440, 329.63, 261.63, 392, 440, 392, 220, 329.63, 440, 523.25, 392, 329.63, 261.63, 329.63];
const BASS = [110, 110, 87.31, 98]; // one note per four melody steps
export const LOOP_SECONDS = MELODY.length * STEP_S;
export const LOOP_NOTES = [
  ...MELODY.map((freq, i) => tone(i * STEP_S, freq, STEP_S * 0.8, "triangle", 0.07)),
  ...BASS.map((freq, i) => tone(i * 4 * STEP_S, freq, STEP_S * 3.6, "sine", 0.1)),
];

/** Run `action`, swallowing any failure: sound is a bonus, so it must never break the game. */
function quiet(action) {
  try {
    return action();
  } catch {
    return undefined;
  }
}

/** The saved mute preference. Sound is on (false) unless "true" was stored. */
export function readMuted(storage) {
  return quiet(() => storage?.getItem(STORAGE_KEY) === "true") ?? false;
}

export function writeMuted(storage, muted) {
  quiet(() => storage?.setItem(STORAGE_KEY, String(muted)));
}

/**
 * The sound engine. `AudioContextClass` is the browser's AudioContext (or undefined),
 * `storage` a localStorage-like object (or null) and `setTimer`/`clearTimer` the timer
 * functions, all injected so tests can substitute them.
 */
export function createSound({ AudioContextClass, storage, setTimer, clearTimer }) {
  let muted = readMuted(storage);
  let broken = typeof AudioContextClass !== "function"; // Web Audio missing or failed to start
  let ctx = null; // created on the first gesture, never before
  let master = null; // the master gain: 1 when sound is on, 0 when muted
  let attemptIsActive = false; // a game is running, so the music should play
  let loop = null; // the music being scheduled, if any

  function open() {
    if (ctx) return true;
    if (broken) return false;
    try {
      ctx = new AudioContextClass();
      master = ctx.createGain();
      master.gain.value = 1;
      master.connect(ctx.destination);
    } catch {
      broken = true;
      ctx = null;
      master = null;
    }
    return ctx !== null;
  }

  const ready = () => ctx !== null && !muted;

  function applyVolume() {
    quiet(() => {
      const now = ctx.currentTime;
      master.gain.cancelScheduledValues(now);
      master.gain.setValueAtTime(muted ? 0 : 1, now);
    });
  }

  /** Queue `notes` starting at `start` on the context clock, into `destination`. */
  function schedule(notes, start, destination) {
    const oscillators = [];
    for (const note of notes) {
      const osc = ctx.createOscillator();
      const envelope = ctx.createGain();
      const begin = start + note.at;
      osc.type = note.type;
      osc.frequency.setValueAtTime(note.freq, begin);
      if (note.to !== note.freq) osc.frequency.exponentialRampToValueAtTime(note.to, begin + note.dur);
      envelope.gain.setValueAtTime(SILENCE, begin);
      envelope.gain.linearRampToValueAtTime(note.gain, begin + ATTACK_S);
      envelope.gain.exponentialRampToValueAtTime(SILENCE, begin + note.dur);
      osc.connect(envelope);
      envelope.connect(destination);
      osc.start(begin);
      osc.stop(begin + note.dur + 0.02);
      oscillators.push(osc);
    }
    return oscillators;
  }

  // Background music: whole passes are queued a few seconds ahead and a timer tops the
  // queue up, so the loop has no gaps even when timers run late.

  function topUp(current) {
    if (loop !== current) return;
    quiet(() => {
      while (current.next < ctx.currentTime + LOOKAHEAD_S) {
        for (const osc of schedule(LOOP_NOTES, current.next, current.gain)) {
          current.oscillators.add(osc);
          osc.onended = () => current.oscillators.delete(osc);
        }
        current.next += LOOP_SECONDS;
      }
    });
    current.timer = setTimer(() => topUp(current), CHECK_MS);
  }

  function startLoop() {
    if (loop) return;
    quiet(() => {
      const gain = ctx.createGain();
      gain.gain.value = 1;
      gain.connect(master);
      loop = { gain, oscillators: new Set(), next: ctx.currentTime + START_DELAY_S, timer: null };
      topUp(loop);
    });
  }

  function stopLoop() {
    if (!loop) return;
    const stopped = loop;
    loop = null;
    clearTimer(stopped.timer);
    quiet(() => {
      const now = ctx.currentTime;
      stopped.gain.gain.cancelScheduledValues(now);
      stopped.gain.gain.setValueAtTime(0, now);
      for (const osc of stopped.oscillators) quiet(() => osc.stop(now));
      stopped.gain.disconnect();
    });
  }

  function syncLoop() {
    if (attemptIsActive && ready()) startLoop();
    else stopLoop();
  }

  /** Called from a user gesture: create (once) and resume the audio context, then start the music if due. */
  function unlock() {
    if (muted || !open()) return;
    quiet(() => {
      if (ctx.state === "suspended") Promise.resolve(ctx.resume()).catch(() => {});
    });
    syncLoop();
  }

  /** React to a cue from game.js. Cues are ignored until the first gesture and while muted. */
  function cue(name) {
    if (name === "active") {
      attemptIsActive = true;
      syncLoop();
      return;
    }
    if (name === "win" || name === "lose") {
      attemptIsActive = false;
      stopLoop();
    }
    const notes = CUES[name];
    if (!notes || !ready()) return;
    quiet(() => schedule(notes, ctx.currentTime + START_DELAY_S, master));
  }

  function setMuted(value) {
    muted = Boolean(value);
    writeMuted(storage, muted);
    if (ctx) applyVolume();
    if (muted) stopLoop();
    else unlock(); // the click that unmutes is itself a gesture
  }

  return {
    cue,
    unlock,
    setMuted,
    toggleMute() {
      setMuted(!muted);
      return muted;
    },
    isMuted: () => muted,
    isSupported: () => !broken,
  };
}

// Page wiring

/** Wire the board page: `doc` and `win` are the document and window, `subscribe` is game.js's onCue. */
export function wire(doc, win, subscribe) {
  let storage = null;
  quiet(() => {
    storage = win.localStorage;
  });
  const sound = createSound({
    AudioContextClass: win.AudioContext ?? win.webkitAudioContext,
    storage,
    setTimer: (callback, ms) => win.setTimeout(callback, ms),
    clearTimer: (id) => win.clearTimeout(id),
  });
  subscribe(sound.cue);
  if (!sound.isSupported()) return sound; // nothing to mute: the button stays hidden

  for (const type of GESTURES) doc.addEventListener(type, () => sound.unlock(), { capture: true, passive: true });

  const button = doc.getElementById("mute-toggle");
  if (button) {
    // aria-pressed is true while the sound is muted; the label names the action the button does next.
    const render = () => {
      const muted = sound.isMuted();
      button.setAttribute("aria-pressed", String(muted));
      button.textContent = muted ? "Activar sonido" : "Silenciar";
    };
    button.addEventListener("click", () => {
      sound.toggleMute();
      render();
    });
    render();
    button.hidden = false;
  }
  return sound;
}

if (typeof document !== "undefined") wire(document, window, onCue);
